DROP TABLE IF EXISTS noticepurchaseprefs;
CREATE TABLE noticepurchaseprefs (
    id integer NOT NULL,
    noticeid integer NOT NULL,
    lotid integer NOT NULL,
    preftype character(1),
    prefcode integer,
    prefvalue numeric(18,2),
    reqcontent character varying(8000)
);

DROP TABLE IF EXISTS sppurchasepreferences;
CREATE TABLE sppurchasepreferences (
    id integer NOT NULL,
    oosid integer NOT NULL,
    shortname character varying(30) NOT NULL,
    code character varying(7) NOT NULL,
    preftype character varying(1) NOT NULL,
    usetenderplans integer NOT NULL
);

DROP TABLE IF EXISTS noticeextdocs;
CREATE TABLE noticeextdocs (
    id integer NOT NULL,
    createdata timestamp(6) without time zone,
    noticeid integer NOT NULL,
    name character varying(100),
    nameext character varying(10),
    binarycontext bytea,
    description character varying(500),
    lotid integer,
    ooscontentid character varying(50),
    filecrcsha256 character varying(100),
    binarycontextid integer,
    doctype integer,
    url character varying(1024)
);

DROP TABLE IF EXISTS noticespec;
CREATE TABLE noticespec (
    id integer NOT NULL,
