    dosagecode integer,
    pripackagecode integer,
    packageq1 numeric(21,11),
    packageq2 integer,
    tradename character varying(500),
    tradeextcode character varying(50),
    ispackreason smallint,
    mempackreason character varying(2000),
    isznvlp smallint,
    dosagegrlsvalue character varying(500),
    medformname character varying(500),
    ktrusuffixcode integer,
    ktruversion integer,
    srcid integer,
    drugchangeobjecttype integer,
    drugchangereasoncode integer,
    drugchangecomment character varying(2000),
    druggrlsref character varying(2000),
    ismedicalproduct integer,
    pripackagename character varying(500),
    sid bigint,
    externalsid character varying(40),
    prodtype smallint,
