    parentspecid integer,
    isequivalentdeliveryallowed smallint,
    isprohibitionforeignpo smallint,
    isrestrictforeignpo smallint,
    ispreferenserfpo smallint,
    isimposibilityprohibition smallint,
    reasonimposibilityprohibition text,
