INSERT INTO noticecustomerrequirements (id, noticeid, lotid, customerregnum, maxprice, deliveryplace, deliveryterm, datestartwork, dateendwork, isapplicationguarantee, aguarantee_amount, aguarantee_part, aguarantee_pinfo, aguarantee_rschet, aguarantee_lschet, aguarantee_bik, iscontractguarantee, cguarantee_amount, cguarantee_part, cguarantee_pinfo, cguarantee_rschet, cguarantee_lschet, cguarantee_bik, addinfo, onesiderejection, plannumber, pglotreestrnumber, ikz, bonumber, bodate, boregistered, purchaseobjectdescription, banksupportcontractrequired, treasurysupportcontractrequired, gguarantee_amount, gguarantee_part, gguarantee_pinfo, gguarantee_rschet, gguarantee_lschet, gguarantee_bik, isguaranteeguarantee, srcid, sizeawans, pg20posnumber, deliverytime, treasurysupportcontracttype, markcolorname, markdesc, localnotes, nonbudgetselffunds, nonrelativestartdate, nonrelativeenddate, relativestart, relativelen, warrantyservicerequirement, manufacturerswarrantyrequirement, warrantyterm, relativestartdaytype, relativeenddaytype, nonrelativeisnotearlierconclusiondate, nonrelativeisfromconclusiondate, ag_iscustomeradmin, ag_inn, ag_kpp, ag_kbk, ag_oktmocode, ag_bankaccount, ag_ksnumber, ag_bik, ag_counterpartyname) VALUES ('18', '18', '18', '01731000170', '800000.00', NULL, '', NULL, NULL, '1', '8000.00', '1.00', 'Обеспечение заявки на участие в закупке предоставляется одним из следующих способов: - путем блокирования денежных средств, внесенных участником закупки на банковский счет, открытый таким участником в банке, включенном в перечень, утвержденный Правительством Российской Федерации (далее - специальный счет). Требования к таким банкам, к договору специального счета, к порядку использования имеющегося у участника закупки банковского счета в качестве специального счета устанавливаются Правительством Российской Федерации; - путем предоставления независимой гарантии, соответствующей требованиям статьи 45 Федерального закона № 44-ФЗ. Выбор способа обеспечения осуществляется участником закупки самостоятельно. Срок действия независимой гарантии должен составлять не менее месяца с даты окончания срока подачи заявок.', '00000000000000000000', 'См. прилагаемые документы', '000000000', '1', '0.00', '5.00', 'Исполнение контракта может обеспечиваться предоставлением независимой гарантии, соответствующей требованиям статьи 45 Федерального закона № 44-ФЗ, или внесением денежных средств на указанный заказчиком счет, на котором в соответствии с законодательством Российской Федерации учитываются операции со средствами, поступающими заказчику. Способ обеспечения исполнения контракта, срок действия независимой гарантии определяются в соответствии с требованиями Федерального закона № 44-ФЗ участником закупки, с которым заключается контракт, самостоятельно. При этом срок действия независимой гарантии должен превышать предусмотренный контрактом срок исполнения обязательств, которые должны быть обеспечены такой независимой гарантией, не менее чем на один месяц, в том числе в случае его изменения в соответствии со статьей 95 Федерального закона № 44-ФЗ. Обеспечение исполнения контракта предоставляется участником закупки, с которым заключается контракт, в срок, установленный для заключения контракта. Контракт заключается после предоставления участником закупки, с которым заключается контракт, обеспечения исполнения контракта. В случае непредоставления участником закупки, с которым заключается контракт, обеспечения исполнения контракта в срок, установленный для заключения контракта, такой участник считается уклонившимся от заключения контракта.', '00000000000000000000', 'См. прилагаемые документы', '000000000', '1. Реквизиты для внесения обеспечения заявки и исполнения контракта: ОГРН 1117746438457, ИНН 7714841940, КПП 771401001; получатель – УФК по г. Москве (Военное следственное управление Следственного комитета Российской Федерации по городу Москве, л/счет 05731F41110), банковский счет 40102810545370000003, казначейский счет 03211643000000017300, банк получателя - ОКЦ № 1 ГУ БАНКА РОССИИ ПО ЦФО//УФК ПО Г. МОСКВЕ г. Москва БИК 004525988. 2. Обеспечение исполнение Контракта не требуется в случаях если: - в соответствии с пунктом 1 части 8 статьи 96 Федерального закона № 44-ФЗ участник закупки, с которым заключается государственный контракт, является казенным учреждением; - в соответствии с частью 8.1 статьи 96 Федерального закона № 44-ФЗ участник закупки, с которым заключается контракт в соответствии с пунктом 1 части 1 статьи 30 Федерального закона № 44-ФЗ представил информацию, содержащуюся в реестре контрактов единой информационной системы, и подтверждающую исполнение таким участником (без учета правопреемства) в течение трех лет до даты подачи заявки на участие в закупке трех контрактов, исполненных без применения к нему неустоек (штрафов, пеней). При этом сумма цен таких контрактов должна составлять не менее начальной (максимальной) цены контракта, указанной в извещении об осуществлении настоящей закупки и документации о ней.', 'Да', '202501731000170001', '202501731000170001000128', '251771484194077140100100100021712244', '001F411125000000761', '2025-12-02 00:00:00', '0', '', '0', '0', '0.00', '0.00', '', '', '', '', '0', NULL, '0.00', '2', '0', NULL, NULL, NULL, NULL, NULL, '2025-12-22', '2026-01-21', '0', '0', 'Поставщик обязан за свой счет устранять дефекты, выявленные в Товаре в течение гарантийного срока, или заменить Товар без изменения его стоимости, если не докажет, что дефекты возникли в результате нарушения Заказчиком правил эксплуатации Товара или его хранения. Расходы на доставку Товара к месту проведения ремонта и обратно относятся на счет Поставщика.', 'Поставляемый Товар должен соответствовать обязательным требованиям к его качеству и безопасности, предусмотренным для Товара данного вида действующим законодательством Российской Федерации, иными правовыми актами Российской Федерации, что должно подтверждаться соответствующими документами.', 'не менее 12 (двенадцати) месяцев с момента приема Товара Заказчиком.', '0', '0', NULL, NULL, '0', '7714841940', '771401001', '41711610051019000140', '45348000', '40102810545370000003', '03100643000000017300', '004525988', 'УПРАВЛЕНИЕ ФЕДЕРАЛЬНОГО КАЗНАЧЕЙСТВА ПО Г. МОСКВЕ (ВСУ СК РОССИИ ПО Г. МОСКВЕ)');
