INSERT INTO noticektruharactvalues (id, noticektruharactid, qualitydesc, okeicode, concretevalue, minmathnotation, rangeminvalue, maxmathnotation, rangemaxvalue, isoutvaluerange) VALUES ('8', '8', 'Вид бумаги для листов: офсетная. Вид крепления: сшивка втачку или потетрадно. Вид обложки: картонная (картон переплетный толщиной не менее 1,75 мм). Нумерация страниц: нет. Ориентация листов: альбомная. Прошнуровка: да.  Формат листов: А4. Вид переплета: твердый из переплетного картона, картон толщиной не менее 1,75 мм, кэширован бумвинилом темно синего цвета, на передней лицевой стороне обложки по центру размещается наклейка (этикетка) с текстом, содержащим наименование книги (согласно образцу Заказчика). Количество листов в блоке: 100. Цвет листов в блоке: белый. Плотность листов в блоке: не менее 80 г/м2. Цвет печати на листах в блоке: черный. Текст на листах в блоке 1+1 согласно представленному образцу Заказчика (отдельно для первой страницы титульного листа, для страниц  со второй до предпоследней и для последней (концевой) страницы).  В нижнем левом углу лицевой стороны блока предусмотрены сквозные отверстия диаметром не менее 2,5 мм и не более 3 мм для прошивки (прошнуровки), отверстия расположены вертикально на расстоянии 1 см друг от друга, расстояние от нижнего отверстия до нижнего края блока 1,5 см, расстояние от отверстий до внутреннего сгиба 1,5 см., 100 листов', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO noticektruharactvalues (id, noticektruharactid, qualitydesc, okeicode, concretevalue, minmathnotation, rangeminvalue, maxmathnotation, rangemaxvalue, isoutvaluerange) VALUES ('9', '9', 'Вид бумаги для листов: офсетная. Вид крепления: сшивка втачку или потетрадно. Вид обложки: картонная (картон переплетный толщиной не менее 1,75 мм). Нумерация страниц: нет. Ориентация листов: альбомная. Прошнуровка: да.  Формат листов: А3. Вид переплета: твердый из переплетного картона, картон толщиной не менее 1,75 мм, кэширован бумвинилом темно синего цвета, на передней лицевой стороне обложки по центру размещается наклейка (этикетка) с текстом, содержащим наименование книги (согласно образцу Заказчика). Количество листов в блоке: 100. Цвет листов в блоке: белый. Плотность листов в блоке: не менее 80 г/м2. Цвет печати на листах в блоке: черный. Текст на листах в блоке 1+1 согласно представленному образцу Заказчика (отдельно для первой страницы титульного листа, для страниц  со второй до предпоследней и для последней (концевой) страницы).  В нижнем левом углу лицевой стороны блока предусмотрены сквозные отверстия диаметром не менее 2,5 мм и не более 3 мм для прошивки (прошнуровки), отверстия расположены вертикально на расстоянии 1 см друг от друга, расстояние от нижнего отверстия до нижнего края блока 1,5 см, расстояние от отверстий до внутреннего сгиба 1,5 см., 100 листов', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
